92. impl<DT: Dispatch> ThreadToken<DT> {
93.     pub open spec fn wf2(&self, num_replicas: nat) -> bool {
94.         &&& self.rid.wf(num_replicas)
95.         &&& self.fc_client@.value().is_Idle()
96.         &&& (self.tid as nat)
97.             < MAX_THREADS_PER_REPLICA
98. 
99.         &&& self.batch_perm@.mem_contents().is_uninit()
100.         &&& self.fc_client@.key() == self.tid as nat
101.     }
102. 
103.     pub open spec fn wf(&self, replica: &Replica<DT>) -> bool {
104.         &&& self.wf2(replica.spec_id() + 1)  
105. 
106.         &&& self.rid@ == replica.spec_id()
107.         &&& self.fc_client@.instance_id() == replica.flat_combiner_instance@.id()
108.         &&& self.batch_perm@@.pcell == replica.contexts[self.thread_id_spec() as int].batch.0.id()
109.     }
110. 
111.     pub fn thread_id(&self) -> (result: ThreadId)
112.         ensures
113.             result as nat == self.thread_id_spec(),
114.     {
115.         self.tid
116.     }
117. 
118.     pub open spec fn thread_id_spec(&self) -> nat {
119.         self.tid as nat
120.     }
121. 
122.     pub const fn replica_id(&self) -> (result: ReplicaId)
123.         ensures
124.             result as nat == self.replica_id_spec(),
125.     {
126.         self.rid.id()
127.     }
128. 
129.     pub open spec fn replica_token(&self) -> ReplicaToken {
130.         self.rid
131.     }
132. 
